create function public.protect_edition() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP='DELETE' then if old.edition is not null then raise exception 'Archive published editions'; end if; return old; end if;
 if TG_OP='UPDATE' and old.edition is not null then
  if new.edition is distinct from old.edition or new.fee_amount_cents is distinct from old.fee_amount_cents or new.currency is distinct from old.currency then raise exception 'Published pricing is immutable'; end if;
  if old.status in ('locked','voting','spotlight','completed') and (new.starts_at<>old.starts_at or new.registration_ends<>old.registration_ends) then raise exception 'Locked schedule is immutable'; end if;
 end if;
 return new;
end $$;
create trigger immutable_edition before update or delete on public.tournaments for each row execute function public.protect_edition();
create function public.protect_bracket() returns trigger language plpgsql set search_path=public as $$
begin
 if old.priority is not null and (new.priority is distinct from old.priority or new.snapshot is distinct from old.snapshot or new.product_id<>old.product_id or new.tournament_id<>old.tournament_id or new.user_id<>old.user_id) then raise exception 'Bracket entries are immutable'; end if;
 return new;
end $$;
create trigger immutable_entry before update on public.entries for each row execute function public.protect_bracket();
create function public.protect_match() returns trigger language plpgsql set search_path=public as $$
begin
 if old.winner_id is not null and (new.winner_id is distinct from old.winner_id or new.score_a is distinct from old.score_a or new.score_b is distinct from old.score_b) then raise exception 'Results are frozen'; end if;
 if new.entry_a<>old.entry_a or new.entry_b<>old.entry_b or new.round<>old.round or new.position<>old.position or new.tournament_id<>old.tournament_id then raise exception 'Pairings are immutable'; end if;
 if (new.starts_at<>old.starts_at or new.ends_at<>old.ends_at) and exists(select 1 from tournaments where id=old.tournament_id and status not in ('cancelled','registration')) then raise exception 'Match schedule is locked'; end if;
 return new;
end $$;
create trigger immutable_match before update on public.matches for each row execute function public.protect_match();

create function public.seat_availability(p_tournament uuid) returns jsonb language sql stable set search_path=public as $$
 select jsonb_build_object('confirmed',c,'reserved',r,'available',greatest(0,8-c-r)) from
 (select count(*) c from entries where tournament_id=p_tournament and status='confirmed') a,
 (select count(*) r from reservations where tournament_id=p_tournament and not released and expires_at>now()) b;
$$;

create function public.admin_command(p_actor uuid,p_action text,p_target uuid default null,p_data jsonb default '{}') returns jsonb language plpgsql set search_path=public as $$
declare t tournaments; e entries; n integer; rid uuid;
begin
 if not exists(select 1 from admin_roles where user_id=p_actor) then raise exception 'Admin access required'; end if;
 if p_action='create' then
  insert into tournaments(theme,registration_ends,starts_at) values(p_data->>'theme',(p_data->>'registration_ends')::timestamptz,(p_data->>'starts_at')::timestamptz) returning id into rid;
 elsif p_action='publish' then
  select * into t from tournaments where id=p_target for update;
  if t.id is null or t.status<>'draft' then raise exception 'Only drafts may be published'; end if;
  update edition_counter set last_edition=last_edition+1 where id returning last_edition into n;
  update tournaments set edition=n,fee_amount_cents=case when n=1 then 0 else 500 end,status='registration' where id=p_target;
 elsif p_action in ('approve','reject','waitlist','remove') then
  select tournament_id into rid from entries where id=p_target;
  select * into t from tournaments where id=rid for update;
  select * into e from entries where id=p_target for update;
  if t.status<>'registration' or now()>=t.registration_ends then raise exception 'Registration is closed'; end if;
  if e.id is null then raise exception 'Entry not found'; end if;
  if p_action='approve' then
   if e.status not in ('pending','waitlisted','approved') then raise exception 'Entry cannot be approved'; end if;
   update reservations set released=true where entry_id=e.id and expires_at<=now();
   if e.status='approved' and exists(select 1 from reservations where entry_id=e.id and not released and expires_at>now()) then return jsonb_build_object('id',e.id); end if;
   if (seat_availability(t.id)->>'available')::int<1 then update entries set status='waitlisted' where id=e.id;
   elsif t.fee_amount_cents=0 then update entries set status='confirmed' where id=e.id; update products set published=true where id=e.product_id;
   else
    if t.registration_ends<now()+interval '31 minutes' then raise exception 'At least 31 minutes needed for payment'; end if;
    update entries set status='approved' where id=e.id;
    insert into reservations(entry_id,tournament_id,expires_at) values(e.id,t.id,least(now()+interval '60 minutes',t.registration_ends));
   end if;
  else
   if e.status='confirmed' and p_action<>'remove' then raise exception 'Use remove for an accepted entry'; end if;
   update entries set status=case p_action when 'reject' then 'rejected' when 'remove' then 'removed' else 'waitlisted' end where id=e.id;
   update reservations set released=true where entry_id=e.id;
   update payments set status='refund_pending' where entry_id=e.id and status='paid';
  end if;
 elsif p_action='cancel' then
  select * into t from tournaments where id=p_target for update;
  if t.status not in ('registration','locked') or now()>=t.starts_at then raise exception 'Only cancel before participation'; end if;
  update tournaments set status='cancelled' where id=t.id;
  update reservations set released=true where tournament_id=t.id;
  update payments set status='refund_pending' where status='paid' and entry_id in(select id from entries where tournament_id=t.id);
  insert into notifications(user_id,message) select user_id,'Edition cancelled. Paid entries will be refunded.' from entries where tournament_id=t.id;
 elsif p_action='reschedule' then
  select * into t from tournaments where id=p_target for update;
  if t.status not in ('registration','cancelled') then raise exception 'Cannot reschedule locked bracket'; end if;
  if t.status='cancelled' and exists(select 1 from payments where entry_id in(select id from entries where tournament_id=t.id) and status in ('paid','refund_pending')) then raise exception 'Finish refunds before rescheduling'; end if;
  if t.status='cancelled' then update entries set status='pending' where tournament_id=t.id; end if;
  update tournaments set status='registration',registration_ends=(p_data->>'registration_ends')::timestamptz,starts_at=(p_data->>'starts_at')::timestamptz where id=t.id;
  update matches set starts_at=(p_data->>'starts_at')::timestamptz+case round when 1 then interval '0 hours' when 2 then interval '24 hours' else interval '40 hours' end,ends_at=(p_data->>'starts_at')::timestamptz+case round when 1 then interval '24 hours' when 2 then interval '40 hours' else interval '48 hours' end where tournament_id=t.id;
  insert into notifications(user_id,message) select user_id,'Your edition was rescheduled. Check the updated schedule.' from entries where tournament_id=t.id;
 elsif p_action='invalidate' then
  if length(coalesce(p_data->>'reason',''))<3 then raise exception 'Reason required'; end if;
  select tournament_id into rid from matches where id=(select match_id from votes where id=p_target);
  perform 1 from tournaments where id=rid for update;
  if not exists(select 1 from matches m join votes v on v.match_id=m.id where v.id=p_target and m.winner_id is null and now()<m.ends_at) then raise exception 'Results already frozen'; end if;
  update votes set valid=false,invalidation_reason=p_data->>'reason' where id=p_target;
 elsif p_action='fulfill' then update promotion_tasks set status='completed',completed_at=now(),draft=coalesce(p_data->>'draft',draft) where id=p_target;
 elsif p_action='interview' then update champions set interview=p_data where tournament_id=p_target;
 elsif p_action='moderate' then update feedback set hidden=true where id=p_target; update reports set status='resolved' where feedback_id=p_target;
 elsif p_action='archive' then update tournaments set archived=true where id=p_target and status in ('completed','cancelled');
 else raise exception 'Unknown admin action'; end if;
 insert into audit_logs(actor,action,target,detail) values(p_actor,p_action,coalesce(p_target,rid),p_data);
 return jsonb_build_object('id',coalesce(rid,p_target));
end $$;

create function public.apply_product(p_actor uuid,p_tournament uuid,p_product jsonb) returns uuid language plpgsql set search_path=public as $$
declare pid uuid; eid uuid; t tournaments;
begin
 select * into t from tournaments where id=p_tournament for update;
 if t.status<>'registration' or now()>=t.registration_ends then raise exception 'Registration is closed'; end if;
 if exists(select 1 from matches where tournament_id=t.id) then raise exception 'Rescheduled locked edition retains its original entrants'; end if;
 insert into products(owner_id,name,slug,url,logo_url,category,tagline,audience,problem,pricing,free_trial,screenshot_url,demo_url,founder,x_handle,question,offer_url)
 values(p_actor,p_product->>'name',p_product->>'slug',p_product->>'url',p_product->>'logo_url',p_product->>'category',p_product->>'tagline',p_product->>'audience',p_product->>'problem',p_product->>'pricing',(p_product->>'free_trial')::boolean,p_product->>'screenshot_url',p_product->>'demo_url',p_product->>'founder',p_product->>'x_handle',p_product->>'question',p_product->>'offer_url') returning id into pid;
 insert into entries(tournament_id,product_id,user_id) values(t.id,pid,p_actor) returning id into eid; return eid;
end $$;
create function public.apply_existing(p_actor uuid,p_tournament uuid,p_product uuid) returns uuid language plpgsql set search_path=public as $$
declare eid uuid; t tournaments;
begin
 select * into t from tournaments where id=p_tournament for update;
 if t.status<>'registration' or now()>=t.registration_ends then raise exception 'Registration is closed'; end if;
 if exists(select 1 from matches where tournament_id=t.id) then raise exception 'Rescheduled locked edition retains its original entrants'; end if;
 if not exists(select 1 from products where id=p_product and owner_id=p_actor) then raise exception 'Product ownership required'; end if;
 insert into entries(tournament_id,product_id,user_id) values(t.id,p_product,p_actor) returning id into eid; return eid;
end $$;

create function public.cast_vote(p_actor uuid,p_match uuid,p_entry uuid) returns void language plpgsql set search_path=public as $$
declare m matches; recent integer;
begin
 select tournament_id into m.tournament_id from matches where id=p_match;
 perform 1 from tournaments where id=m.tournament_id for update;
 select * into m from matches where id=p_match for update;
 if not exists(select 1 from auth.users where id=p_actor and (email_confirmed_at is not null or raw_app_meta_data->>'provider'='github' or raw_app_meta_data->'providers' ? 'github')) then raise exception 'Verified account required'; end if;
 if m.id is null or clock_timestamp()<m.starts_at or clock_timestamp()>=m.ends_at or m.winner_id is not null or not exists(select 1 from tournaments where id=m.tournament_id and status='voting') then raise exception 'Match is not open'; end if;
 if p_entry not in (m.entry_a,m.entry_b) then raise exception 'Invalid contender'; end if;
 if exists(select 1 from entries where id in (m.entry_a,m.entry_b) and user_id=p_actor) then raise exception 'Founders cannot vote in their own match'; end if;
 select count(*) into recent from votes where user_id=p_actor and created_at>now()-interval '1 minute';
 if recent>=10 then raise exception 'Please slow down'; end if;
 insert into votes(match_id,entry_id,user_id,suspicious) values(m.id,p_entry,p_actor,(select created_at>now()-interval '1 hour' from auth.users where id=p_actor));
end $$;

create function public.match_scores(p_match uuid) returns jsonb language sql stable set search_path=public as $$
 select jsonb_build_object('a',coalesce(m.score_a,(select count(*) from votes where match_id=m.id and entry_id=m.entry_a and valid)), 'b',coalesce(m.score_b,(select count(*) from votes where match_id=m.id and entry_id=m.entry_b and valid))) from matches m where id=p_match;
$$;

create function public.fulfill_payment(p_event text,p_type text,p_entry uuid,p_checkout text,p_intent text,p_amount integer,p_currency text,p_reservation uuid) returns text language plpgsql set search_path=public as $$
declare e entries; t tournaments; r reservations; existing payments; decision text;
begin
 select tournament_id into e.tournament_id from entries where id=p_entry;
 select * into t from tournaments where id=e.tournament_id for update;
 select * into e from entries where id=p_entry for update;
 if t.id is null or p_amount<>t.fee_amount_cents or p_currency<>t.currency or p_amount<>500 then raise exception 'Payment metadata or amount mismatch'; end if;
 select * into r from reservations where id=p_reservation and entry_id=e.id;
 if r.id is null then raise exception 'Checkout mismatch'; end if;
 if exists(select 1 from webhook_events where id=p_event) then return 'duplicate'; end if;
 select * into existing from payments where intent_id=p_intent;
 if existing.id is not null then insert into webhook_events(id,type) values(p_event,p_type); return 'duplicate'; end if;
 -- Release expired reservations under the tournament lock; delayed payments can only take a real seat.
 update reservations set released=true where tournament_id=t.id and expires_at<=now();
 decision='refund_pending';
 if e.status='approved' and t.status='registration' and now()<t.registration_ends and now()<t.starts_at and (r.checkout_id is null or r.checkout_id=p_checkout) and not exists(select 1 from payment_signals where intent_id=p_intent) then
  if (not r.released and r.expires_at>now()) or (seat_availability(t.id)->>'available')::int>0 then
   decision='paid'; update entries set status='confirmed' where id=e.id; update products set published=true where id=e.product_id;
  end if;
 end if;
 select coalesce((select status from payment_signals where intent_id=p_intent),decision) into decision;
 insert into payments(entry_id,checkout_id,intent_id,amount,currency,status) values(e.id,p_checkout,p_intent,p_amount,p_currency,decision);
 update reservations set released=true where id=r.id;
 insert into webhook_events(id,type) values(p_event,p_type);
 return decision;
end $$;

create function public.record_payment_signal(p_event text,p_type text,p_intent text,p_entry uuid,p_status text) returns void language plpgsql set search_path=public as $$
declare tid uuid;
begin
 select tournament_id into tid from entries where id=p_entry;
 if tid is null then raise exception 'Entry not found'; end if;
 perform 1 from tournaments where id=tid for update;
 if exists(select 1 from webhook_events where id=p_event) then return; end if;
 insert into payment_signals(intent_id,entry_id,status) values(p_intent,p_entry,p_status) on conflict(intent_id) do update set status=excluded.status,updated_at=now();
 update payments set status=p_status where intent_id=p_intent;
 insert into webhook_events(id,type) values(p_event,p_type);
end $$;

create function public.tick() returns void language plpgsql set search_path=public as $$
declare t tournaments; m matches; ids uuid[]; winners uuid[]; a integer; b integer; win uuid; roundno integer; offsethours integer; durationhours integer; i integer;
begin
 for t in select * from tournaments where status in ('registration','locked','voting','spotlight') order by edition for update skip locked loop
  update reservations set released=true where tournament_id=t.id and expires_at<=now();
  if t.status='registration' and now()>=t.registration_ends then
   if (select count(*) from entries where tournament_id=t.id and status='confirmed')<>8 then
    update tournaments set starts_at=greatest(now()+interval '25 hours',starts_at+interval '7 days'),registration_ends=greatest(now()+interval '24 hours',registration_ends+interval '7 days') where id=t.id;
    insert into notifications(user_id,message) select user_id,'Voting was rescheduled because eight confirmed entrants are required.' from entries where tournament_id=t.id;
    continue;
   end if;
   if not exists(select 1 from matches where tournament_id=t.id) then
    select array_agg(id) into ids from (select id from entries where tournament_id=t.id and status='confirmed' order by random()) x;
    for i in 1..8 loop update entries set priority=i,snapshot=(select to_jsonb(p) from products p where p.id=entries.product_id) where id=ids[i]; end loop;
    for i in 1..4 loop insert into matches(tournament_id,round,position,entry_a,entry_b,starts_at,ends_at) values(t.id,1,i,ids[i*2-1],ids[i*2],t.starts_at,t.starts_at+interval '24 hours'); end loop;
   end if;
   update tournaments set status='locked' where id=t.id;
   if not exists(select 1 from promotion_tasks where tournament_id=t.id and kind='announcement') then
    insert into promotion_tasks(tournament_id,kind,draft) values(t.id,'announcement','SummitWar edition #'||t.edition||': '||(select string_agg(snapshot->>'name',', ' order by priority) from entries where tournament_id=t.id and status='confirmed')||'. Watch the demos and choose the app you would actually use. Battle: /tournaments/'||t.id);
    insert into promotion_tasks(tournament_id,entry_id,kind,draft) select t.id,id,'battle_card','Download your battle card from your match page.' from entries where tournament_id=t.id;
   end if;
   t.status='locked';
  end if;
  if t.status='locked' and now()>=t.starts_at then update tournaments set status='voting' where id=t.id; t.status='voting'; end if;
  if t.status='voting' then
   for roundno in 1..3 loop
    for m in select * from matches where tournament_id=t.id and round=roundno and ends_at<=now() and winner_id is null order by position for update loop
     select count(*) into a from votes where match_id=m.id and entry_id=m.entry_a and valid;
     select count(*) into b from votes where match_id=m.id and entry_id=m.entry_b and valid;
     if a=b then select id into win from entries where id in(m.entry_a,m.entry_b) order by priority limit 1; else win=case when a>b then m.entry_a else m.entry_b end; end if;
     update matches set winner_id=win,score_a=a,score_b=b where id=m.id;
    end loop;
    if (select count(*) from matches where tournament_id=t.id and round=roundno and winner_id is not null) = (case roundno when 1 then 4 when 2 then 2 else 1 end) then
     select array_agg(winner_id order by position) into winners from matches where tournament_id=t.id and round=roundno;
     if roundno<3 then
      offsethours=case roundno when 1 then 24 else 40 end; durationhours=case roundno when 1 then 16 else 8 end;
      for i in 1..(array_length(winners,1)/2) loop insert into matches(tournament_id,round,position,entry_a,entry_b,starts_at,ends_at) values(t.id,roundno+1,i,winners[i*2-1],winners[i*2],t.starts_at+make_interval(hours=>offsethours),t.starts_at+make_interval(hours=>offsethours+durationhours)) on conflict do nothing; end loop;
     else
      insert into champions(tournament_id,entry_id,spotlight_starts,spotlight_ends) values(t.id,winners[1],t.starts_at+interval '48 hours',t.starts_at+interval '168 hours') on conflict do nothing;
      update tournaments set status='spotlight' where id=t.id;
      if not exists(select 1 from promotion_tasks where tournament_id=t.id and kind='champion_post') then
       insert into promotion_tasks(tournament_id,entry_id,kind,draft) values(t.id,winners[1],'champion_post',(select snapshot->>'name' from entries where id=winners[1])||' is the community-choice champion of SummitWar edition #'||t.edition||'. Discover what they built: /champions/'||t.id),(t.id,winners[1],'pin_post','Pin the dedicated X post for five days.'),(t.id,winners[1],'founder_interview','What did you build? Who does it help? Why did you build it?');
      end if;
     end if;
    end if;
   end loop;
  end if;
  if now()>=t.starts_at+interval '168 hours' and exists(select 1 from champions where tournament_id=t.id) then update tournaments set status='completed' where id=t.id; end if;
 end loop;
end $$;

create function public.add_feedback(p_actor uuid,p_product uuid,p_body text) returns void language plpgsql set search_path=public as $$
begin
 perform pg_advisory_xact_lock(hashtext(p_actor::text));
 if (select count(*) from feedback where user_id=p_actor and created_at>now()-interval '1 minute')>=3 then raise exception 'Please slow down'; end if;
 if not exists(select 1 from products where id=p_product and published) then raise exception 'Product unavailable'; end if;
 insert into feedback(product_id,user_id,body) values(p_product,p_actor,p_body);
end $$;

-- No direct mutations for public roles. Only trusted server commands above may mutate.
do $$ declare name text; begin
 foreach name in array array['admin_roles','profiles','products','edition_counter','tournaments','entries','reservations','matches','votes','feedback','reports','payments','webhook_events','payment_signals','champions','analytics_events','promotion_tasks','audit_logs','notifications'] loop
  execute format('alter table public.%I enable row level security',name);
  execute format('revoke all on public.%I from anon, authenticated',name);
  execute format('grant all on public.%I to service_role',name);
 end loop;
end $$;
grant select on products,tournaments,entries,matches,feedback,champions,promotion_tasks to anon,authenticated;
create policy published_products on products for select to anon,authenticated using(published or owner_id=(select auth.uid()));
create policy published_tournaments on tournaments for select to anon,authenticated using(edition is not null);
create policy confirmed_entries on entries for select to anon,authenticated using(status='confirmed' or user_id=(select auth.uid()));
create policy public_matches on matches for select to anon,authenticated using(true);
create policy visible_feedback on feedback for select to anon,authenticated using(not hidden);
create policy public_champions on champions for select to anon,authenticated using(true);
create policy public_benefits on promotion_tasks for select to anon,authenticated using(true);
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on all functions in schema public to service_role;
grant usage,select on all sequences in schema public to service_role;

-- END 20261011160707_summitwar.sql

-- BEGIN 20261011172940_simplify_submissions.sql
-- Upgrade existing installations without changing published edition identities.
alter table public.products alter column audience drop not null;
alter table public.products alter column problem drop not null;
alter table public.products alter column pricing drop not null;
alter table public.products alter column screenshot_url drop not null;
alter table public.products alter column demo_url drop not null;
alter table public.products alter column question drop not null;
alter table public.entries add column registration_slot integer check(registration_slot between 1 and 8);
alter table public.entries add column review_status text not null default 'pending' check(review_status in ('pending','approved','rejected'));
update public.entries set review_status='approved' where status in ('approved','confirmed');
with placed as (select e.id,row_number() over(partition by e.tournament_id order by e.created_at,e.id) slot from entries e where e.status='confirmed' or exists(select 1 from reservations r where r.entry_id=e.id and not r.released and r.expires_at>now()))
update entries set registration_slot=placed.slot from placed where entries.id=placed.id and placed.slot<=8;
create unique index confirmed_place_unique on public.entries(tournament_id,registration_slot) where status='confirmed' and registration_slot is not null;

create table public.site_lookup_requests(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create index site_lookup_rate on public.site_lookup_requests(user_id,created_at);
alter table public.site_lookup_requests enable row level security;
revoke all on public.site_lookup_requests from anon,authenticated;
grant all on public.site_lookup_requests to service_role;
grant usage,select on sequence public.site_lookup_requests_id_seq to service_role;
create function public.limit_site_lookup(p_actor uuid) returns void language plpgsql set search_path=public as $$
begin
 perform pg_advisory_xact_lock(hashtext(p_actor::text));
 if (select count(*) from site_lookup_requests where user_id=p_actor and created_at>now()-interval '1 minute')>=12 or (select count(*) from site_lookup_requests where user_id=p_actor and created_at>now()-interval '1 hour')>=60 then raise exception 'Please wait before fetching another website'; end if;
 delete from site_lookup_requests where created_at<now()-interval '24 hours';
 insert into site_lookup_requests(user_id) values(p_actor);
end $$;

create or replace function public.seat_availability(p_tournament uuid) returns jsonb language sql stable set search_path=public as $$
 select jsonb_build_object('confirmed',c,'reserved',r,'available',greatest(0,8-c-r),'booked_slots',coalesce((select jsonb_agg(slot order by slot) from(select distinct e.registration_slot slot from entries e where e.tournament_id=p_tournament and e.registration_slot is not null and (e.status='confirmed' or exists(select 1 from reservations r where r.entry_id=e.id and not r.released and r.expires_at>now()))) slots),'[]'::jsonb)) from
 (select count(*) c from entries where tournament_id=p_tournament and status='confirmed') a,
 (select count(*) r from reservations where tournament_id=p_tournament and not released and expires_at>now() and entry_id not in(select id from entries where status='confirmed')) b;
$$;

create function public.submit_application(p_actor uuid,p_tournament uuid,p_product jsonb,p_slot integer default null,p_existing uuid default null) returns jsonb language plpgsql set search_path=public as $$
declare t tournaments; e entries; pid uuid; eid uuid; chosen integer; occupied integer[]; r reservations;
begin
 select * into t from tournaments where id=p_tournament for update;
 if t.id is null or t.status<>'registration' or clock_timestamp()>=t.registration_ends then raise exception 'Registration is closed'; end if;
 if exists(select 1 from matches where tournament_id=t.id) then raise exception 'Rescheduled bracket retains its original founders'; end if;
 update reservations set released=true where tournament_id=t.id and expires_at<=clock_timestamp();
 select * into e from entries where tournament_id=t.id and user_id=p_actor;
 if e.id is not null then
  if p_existing is not null and p_existing<>e.product_id then raise exception 'Resume the app you already submitted from your dashboard';end if;
  if p_product->>'url' is not null and not exists(select 1 from products where id=e.product_id and normalized_url=regexp_replace(regexp_replace(regexp_replace(lower(p_product->>'url'),'^https?://(www[.])?','','i'),'[?#].*$','','g'),'/+$','','g')) then raise exception 'You already submitted a different app to this tournament';end if;
  select * into r from reservations where entry_id=e.id and not released and expires_at>clock_timestamp();
  if e.status='confirmed' or r.id is not null then
   return jsonb_build_object('entry',e.id,'status',e.status,'fee',t.fee_amount_cents,'slot',e.registration_slot,'review_status',e.review_status);
  end if;
  if e.status not in ('pending','approved') then raise exception 'You have already applied to this tournament'; end if;
  -- An expired checkout can only reclaim its original application; content stays unchanged.
  pid=e.product_id;
 else
  if p_existing is not null then
   if not exists(select 1 from products where id=p_existing and owner_id=p_actor) then raise exception 'Product ownership required'; end if;
   pid=p_existing;
  else
   insert into products(owner_id,name,slug,url,logo_url,category,tagline,founder,x_handle,free_trial)
   values(p_actor,p_product->>'name',p_product->>'slug',p_product->>'url',p_product->>'logo_url',p_product->>'category',coalesce(p_product->>'tagline',''),p_product->>'founder',p_product->>'x_handle',false) returning id into pid;
  end if;
 end if;
 select coalesce(array_agg(claim.registration_slot),'{}'::integer[]) into occupied from entries claim where claim.tournament_id=t.id and claim.registration_slot is not null and (claim.status='confirmed' or exists(select 1 from reservations booking where booking.entry_id=claim.id and not booking.released and booking.expires_at>clock_timestamp()));
 if p_slot is not null then
  if p_slot not between 1 and 8 or p_slot=any(occupied) then raise exception 'This place is already taken. Choose another open place'; end if;
  chosen=p_slot;
 else select slot into chosen from generate_series(1,8) slot where not(slot=any(occupied)) order by slot limit 1; end if;
 if chosen is null or (seat_availability(t.id)->>'available')::int<1 then raise exception 'All eight places are already taken'; end if;
 if t.fee_amount_cents>0 and t.registration_ends<clock_timestamp()+interval '31 minutes' then raise exception 'Registration needs at least 31 minutes remaining for checkout'; end if;
 if e.id is null then insert into entries(tournament_id,product_id,user_id,status,registration_slot,review_status) values(t.id,pid,p_actor,case when t.fee_amount_cents=0 then 'pending' else 'approved' end,chosen,'pending') returning id into eid;
 else eid=e.id;update entries set status=case when t.fee_amount_cents=0 then 'pending' else 'approved' end,registration_slot=chosen where id=eid;end if;
 insert into reservations(entry_id,tournament_id,expires_at) values(eid,t.id,case when t.fee_amount_cents=0 then t.registration_ends else least(clock_timestamp()+interval '60 minutes',t.registration_ends) end);
 return jsonb_build_object('entry',eid,'status',case when t.fee_amount_cents=0 then 'pending' else 'approved' end,'fee',t.fee_amount_cents,'slot',chosen,'review_status','pending');
end $$;

-- Keep existing organizer logic, wrapping the old function to support submitted
-- reservations and paid entries still awaiting review.
alter function public.admin_command(uuid,text,uuid,jsonb) rename to admin_command_before_submission;
create function public.admin_command(p_actor uuid,p_action text,p_target uuid default null,p_data jsonb default '{}') returns jsonb language plpgsql set search_path=public as $$
declare e entries; t tournaments; slot integer;
begin
 if not exists(select 1 from admin_roles where user_id=p_actor) then raise exception 'Admin access required'; end if;
 if p_action in ('approve','reject','waitlist','remove') then
  select tournament_id into e.tournament_id from entries where id=p_target;
  select * into t from tournaments where id=e.tournament_id for update;
  select * into e from entries where id=p_target for update;
  if t.status<>'registration' or clock_timestamp()>=t.registration_ends then raise exception 'Registration is closed'; end if;
  if p_action='approve' then
   if e.status='confirmed' then update entries set review_status='approved' where id=e.id;update products set published=true where id=e.product_id;
   elsif t.fee_amount_cents=0 and exists(select 1 from reservations where entry_id=e.id and not released and expires_at>clock_timestamp()) then
    update reservations set released=true where entry_id=e.id;update entries set status='confirmed',review_status='approved' where id=e.id;update products set published=true where id=e.product_id;
   else
    perform admin_command_before_submission(p_actor,p_action,p_target,p_data);
    update entries set review_status='approved' where id=e.id;
    if exists(select 1 from entries where id=e.id and status='confirmed') then update products set published=true where id=e.product_id;end if;
    if e.registration_slot is null then
     select candidate into slot from generate_series(1,8) candidate where not exists(select 1 from entries other where other.tournament_id=t.id and other.registration_slot=candidate and other.id<>e.id and (other.status='confirmed' or exists(select 1 from reservations r where r.entry_id=other.id and not r.released and r.expires_at>now()))) order by candidate limit 1;
     update entries set registration_slot=slot where id=e.id;
    end if;
   end if;
  elsif p_action in ('reject','waitlist') and e.status='confirmed' and e.review_status='pending' then
   update entries set status=case when p_action='reject' then 'rejected' else 'waitlisted' end,review_status=case when p_action='reject' then 'rejected' else 'pending' end,registration_slot=null where id=e.id;
   update reservations set released=true where entry_id=e.id;update payments set status='refund_pending' where entry_id=e.id and status='paid';
  else perform admin_command_before_submission(p_actor,p_action,p_target,p_data);update entries set registration_slot=null,review_status=case when p_action in ('reject','remove') then 'rejected' else 'pending' end where id=e.id;end if;
  insert into audit_logs(actor,action,target,detail) values(p_actor,'review_'||p_action,p_target,p_data);
  return jsonb_build_object('id',e.id);
 end if;
 return admin_command_before_submission(p_actor,p_action,p_target,p_data);
end $$;

-- Publishing is contingent on organizer review; a paid seat can stay private
-- until approval, and rejected paid submissions enter the refund queue.
create function public.publish_reviewed_entry() returns trigger language plpgsql set search_path=public as $$
begin
 if new.published and not old.published and exists(select 1 from entries where product_id=new.id and status='confirmed') and not exists(select 1 from entries where product_id=new.id and status='confirmed' and review_status='approved') then new.published=false;end if;
 return new;
end $$;
create trigger require_entry_review before update of published on products for each row execute function publish_reviewed_entry();
alter function public.tick() rename to tick_before_submission;
create function public.tick() returns void language plpgsql set search_path=public as $$
declare t tournaments;
begin
 for t in select * from tournaments where status='registration' and registration_ends<=now() and exists(select 1 from entries where tournament_id=tournaments.id and status='confirmed' and review_status<>'approved') for update skip locked loop
  update tournaments set registration_ends=greatest(now()+interval '24 hours',registration_ends+interval '7 days'),starts_at=greatest(now()+interval '25 hours',starts_at+interval '7 days') where id=t.id;
  insert into notifications(user_id,message) select user_id,'Voting was rescheduled because all eight participants must pass organizer review.' from entries where tournament_id=t.id;
 end loop;
 perform tick_before_submission();
end $$;
revoke execute on function public.tick(),public.tick_before_submission() from public,anon,authenticated;
grant execute on function public.tick(),public.tick_before_submission() to service_role;
revoke execute on function public.limit_site_lookup(uuid),public.submit_application(uuid,uuid,jsonb,integer,uuid),public.admin_command(uuid,text,uuid,jsonb),public.admin_command_before_submission(uuid,text,uuid,jsonb),public.publish_reviewed_entry() from public,anon,authenticated;
grant execute on function public.limit_site_lookup(uuid),public.submit_application(uuid,uuid,jsonb,integer,uuid),public.admin_command(uuid,text,uuid,jsonb),public.admin_command_before_submission(uuid,text,uuid,jsonb),public.publish_reviewed_entry() to service_role;

-- A delayed payment may not occupy another founder's claimed place.
create or replace function public.fulfill_payment(p_event text,p_type text,p_entry uuid,p_checkout text,p_intent text,p_amount integer,p_currency text,p_reservation uuid) returns text language plpgsql set search_path=public as $$
declare e entries; t tournaments; r reservations; existing payments; decision text;
begin
 select tournament_id into e.tournament_id from entries where id=p_entry;
 select * into t from tournaments where id=e.tournament_id for update;
 select * into e from entries where id=p_entry for update;
 if t.id is null or p_amount<>t.fee_amount_cents or p_currency<>t.currency or p_amount<>500 then raise exception 'Payment metadata or amount mismatch'; end if;
 select * into r from reservations where id=p_reservation and entry_id=e.id;
 if r.id is null then raise exception 'Checkout mismatch'; end if;
 if exists(select 1 from webhook_events where id=p_event) then return 'duplicate'; end if;
 select * into existing from payments where intent_id=p_intent;
 if existing.id is not null then insert into webhook_events(id,type) values(p_event,p_type); return 'duplicate'; end if;
 -- Release expired reservations under the tournament lock; delayed payments can only take a real seat.
 update reservations set released=true where tournament_id=t.id and expires_at<=now();
 decision='refund_pending';
 if e.status='approved' and t.status='registration' and now()<t.registration_ends and now()<t.starts_at and (r.checkout_id is null or r.checkout_id=p_checkout) and not exists(select 1 from payment_signals where intent_id=p_intent)
  and (e.registration_slot is null or not exists(select 1 from entries other where other.tournament_id=t.id and other.id<>e.id and other.registration_slot=e.registration_slot and (other.status='confirmed' or exists(select 1 from reservations occupied where occupied.entry_id=other.id and not occupied.released and occupied.expires_at>clock_timestamp())))) then
  if (not r.released and r.expires_at>now()) or (seat_availability(t.id)->>'available')::int>0 then
   decision='paid'; update entries set status='confirmed' where id=e.id; update products set published=true where id=e.product_id;
  end if;
 end if;
 select coalesce((select status from payment_signals where intent_id=p_intent),decision) into decision;
 insert into payments(entry_id,checkout_id,intent_id,amount,currency,status) values(e.id,p_checkout,p_intent,p_amount,p_currency,decision);
 update reservations set released=true where id=r.id;
 insert into webhook_events(id,type) values(p_event,p_type);
 return decision;
end $$;

-- END 20261011172940_simplify_submissions.sql

-- BEGIN 20261011184518_visitor_presence.sql
create table public.site_visitors(visitor_hash text primary key check(visitor_hash ~ '^[0-9a-f]{64}$'),last_seen timestamptz not null default now());
create index site_visitors_active on public.site_visitors(last_seen);
create table public.site_visit_totals(id boolean primary key default true check(id),total bigint not null default 0 check(total>=0));
insert into public.site_visit_totals(id,total) values(true,0);
alter table public.site_visitors enable row level security;
alter table public.site_visit_totals enable row level security;
revoke all on public.site_visitors,public.site_visit_totals from public,anon,authenticated;
grant select,insert,update,delete on public.site_visitors,public.site_visit_totals to service_role;
create function public.register_site_visit(p_visitor text) returns jsonb language plpgsql set search_path=public as $$
declare seen timestamptz; current_time_value timestamptz=clock_timestamp();
begin
 if p_visitor is null or p_visitor !~ '^[0-9a-f]{64}$' then raise exception 'Invalid visitor';end if;
 perform pg_advisory_xact_lock(hashtext(p_visitor));
 select last_seen into seen from site_visitors where visitor_hash=p_visitor for update;
 if seen is null or seen<current_time_value-interval '30 minutes' then update site_visit_totals set total=total+1 where id=true;end if;
 insert into site_visitors(visitor_hash,last_seen) values(p_visitor,current_time_value) on conflict(visitor_hash) do update set last_seen=excluded.last_seen where site_visitors.last_seen<current_time_value-interval '15 seconds';
 delete from site_visitors where last_seen<current_time_value-interval '90 days';
 return jsonb_build_object('current',(select count(*) from site_visitors where last_seen>current_time_value-interval '90 seconds'),'total',(select total from site_visit_totals where id=true));
end $$;
revoke execute on function public.register_site_visit(text) from public,anon,authenticated;
grant execute on function public.register_site_visit(text) to service_role;

-- END 20261011184518_visitor_presence.sql

-- BEGIN 20261011190335_daily_tournaments.sql
-- Preserve already locked brackets and historical champions; new editions use the daily cycle.
alter table public.tournaments add column daily_cycle boolean not null default false;
update public.tournaments set daily_cycle=true where status in ('draft','registration') and not exists(select 1 from matches where tournament_id=tournaments.id);
alter table public.tournaments alter column daily_cycle set default true;
alter table public.tournaments add column previous_tournament_id uuid unique references public.tournaments(id);
alter table public.champions drop constraint champions_check;
alter table public.champions add constraint champion_spotlight_duration check(spotlight_ends=spotlight_starts+interval '12 hours' or spotlight_ends=spotlight_starts+interval '120 hours');
create function public.next_daily_start(p_start timestamptz) returns timestamptz language sql stable set search_path=public as $$
 select p_start+make_interval(hours=>24*greatest(1,ceil(extract(epoch from(now()+interval '1 hour'-p_start))/86400)::integer));
$$;
create or replace function public.admin_command_before_submission(p_actor uuid,p_action text,p_target uuid default null,p_data jsonb default '{}') returns jsonb language plpgsql set search_path=public as $$
declare t tournaments; e entries; n integer; rid uuid;
begin
 if not exists(select 1 from admin_roles where user_id=p_actor) then raise exception 'Admin access required'; end if;
 if p_action='create' then
  insert into tournaments(theme,registration_ends,starts_at) values(p_data->>'theme',(p_data->>'registration_ends')::timestamptz,(p_data->>'starts_at')::timestamptz) returning id into rid;
 elsif p_action='publish' then
  select * into t from tournaments where id=p_target for update;
  if t.id is null or t.status<>'draft' then raise exception 'Only drafts may be published'; end if;
  update edition_counter set last_edition=last_edition+1 where id returning last_edition into n;
  update tournaments set edition=n,fee_amount_cents=case when n=1 then 0 else 500 end,status='registration' where id=p_target;
 elsif p_action in ('approve','reject','waitlist','remove') then
  select tournament_id into rid from entries where id=p_target;
  select * into t from tournaments where id=rid for update;
  select * into e from entries where id=p_target for update;
  if t.status<>'registration' or now()>=t.registration_ends then raise exception 'Registration is closed'; end if;
  if e.id is null then raise exception 'Entry not found'; end if;
  if p_action='approve' then
   if e.status not in ('pending','waitlisted','approved') then raise exception 'Entry cannot be approved'; end if;
   update reservations set released=true where entry_id=e.id and expires_at<=now();
   if e.status='approved' and exists(select 1 from reservations where entry_id=e.id and not released and expires_at>now()) then return jsonb_build_object('id',e.id); end if;
   if (seat_availability(t.id)->>'available')::int<1 then update entries set status='waitlisted' where id=e.id;
   elsif t.fee_amount_cents=0 then update entries set status='confirmed' where id=e.id; update products set published=true where id=e.product_id;
   else
    if t.registration_ends<now()+interval '31 minutes' then raise exception 'At least 31 minutes needed for payment'; end if;
    update entries set status='approved' where id=e.id;
    insert into reservations(entry_id,tournament_id,expires_at) values(e.id,t.id,least(now()+interval '60 minutes',t.registration_ends));
   end if;
  else
   if e.status='confirmed' and p_action<>'remove' then raise exception 'Use remove for an accepted entry'; end if;
   update entries set status=case p_action when 'reject' then 'rejected' when 'remove' then 'removed' else 'waitlisted' end where id=e.id;
   update reservations set released=true where entry_id=e.id;
   update payments set status='refund_pending' where entry_id=e.id and status='paid';
  end if;
 elsif p_action='cancel' then
  select * into t from tournaments where id=p_target for update;
  if t.status not in ('registration','locked') or now()>=t.starts_at then raise exception 'Only cancel before participation'; end if;
  update tournaments set status='cancelled' where id=t.id;
  update reservations set released=true where tournament_id=t.id;
  update payments set status='refund_pending' where status='paid' and entry_id in(select id from entries where tournament_id=t.id);
  insert into notifications(user_id,message) select user_id,'Edition cancelled. Paid entries will be refunded.' from entries where tournament_id=t.id;
 elsif p_action='reschedule' then
  select * into t from tournaments where id=p_target for update;
  if t.status not in ('registration','cancelled') then raise exception 'Cannot reschedule locked bracket'; end if;
  if t.status='cancelled' and exists(select 1 from payments where entry_id in(select id from entries where tournament_id=t.id) and status in ('paid','refund_pending')) then raise exception 'Finish refunds before rescheduling'; end if;
  if t.status='cancelled' then update entries set status='pending' where tournament_id=t.id; end if;
  update tournaments set status='registration',registration_ends=(p_data->>'registration_ends')::timestamptz,starts_at=(p_data->>'starts_at')::timestamptz where id=t.id;
  update matches set starts_at=(p_data->>'starts_at')::timestamptz+make_interval(hours=>case when t.daily_cycle then (round-1)*4 else case round when 1 then 0 when 2 then 24 else 40 end end),ends_at=(p_data->>'starts_at')::timestamptz+make_interval(hours=>case when t.daily_cycle then round*4 else case round when 1 then 24 when 2 then 40 else 48 end end) where tournament_id=t.id;
  insert into notifications(user_id,message) select user_id,'Your edition was rescheduled. Check the updated schedule.' from entries where tournament_id=t.id;
 elsif p_action='invalidate' then
  if length(coalesce(p_data->>'reason',''))<3 then raise exception 'Reason required'; end if;
  select tournament_id into rid from matches where id=(select match_id from votes where id=p_target);
  perform 1 from tournaments where id=rid for update;
  if not exists(select 1 from matches m join votes v on v.match_id=m.id where v.id=p_target and m.winner_id is null and now()<m.ends_at) then raise exception 'Results already frozen'; end if;
  update votes set valid=false,invalidation_reason=p_data->>'reason' where id=p_target;
 elsif p_action='fulfill' then update promotion_tasks set status='completed',completed_at=now(),draft=coalesce(p_data->>'draft',draft) where id=p_target;
 elsif p_action='interview' then update champions set interview=p_data where tournament_id=p_target;
 elsif p_action='moderate' then update feedback set hidden=true where id=p_target; update reports set status='resolved' where feedback_id=p_target;
 elsif p_action='archive' then update tournaments set archived=true where id=p_target and status in ('completed','cancelled');
 else raise exception 'Unknown admin action'; end if;
 insert into audit_logs(actor,action,target,detail) values(p_actor,p_action,coalesce(p_target,rid),p_data);
 return jsonb_build_object('id',coalesce(rid,p_target));
end $$;

create or replace function public.tick_before_submission() returns void language plpgsql set search_path=public as $$
declare t tournaments; m matches; ids uuid[]; winners uuid[]; a integer; b integer; win uuid; roundno integer; offsethours integer; durationhours integer; i integer;
begin
 for t in select * from tournaments where status in ('registration','locked','voting','spotlight') order by edition for update skip locked loop
  update reservations set released=true where tournament_id=t.id and expires_at<=now();
  if t.status='registration' and now()>=t.registration_ends then
   if (select count(*) from entries where tournament_id=t.id and status='confirmed')<>8 then
    update tournaments set starts_at=public.next_daily_start(starts_at),registration_ends=public.next_daily_start(starts_at)-interval '1 hour' where id=t.id;
    insert into notifications(user_id,message) select user_id,'Voting was rescheduled because eight confirmed entrants are required.' from entries where tournament_id=t.id;
    continue;
   end if;
   if not exists(select 1 from matches where tournament_id=t.id) then
    select array_agg(id) into ids from (select id from entries where tournament_id=t.id and status='confirmed' order by random()) x;
    for i in 1..8 loop update entries set priority=i,snapshot=(select to_jsonb(p) from products p where p.id=entries.product_id) where id=ids[i]; end loop;
    for i in 1..4 loop insert into matches(tournament_id,round,position,entry_a,entry_b,starts_at,ends_at) values(t.id,1,i,ids[i*2-1],ids[i*2],t.starts_at,t.starts_at+make_interval(hours=>case when t.daily_cycle then 4 else 24 end)); end loop;
   end if;
   update tournaments set status='locked' where id=t.id;
   if not exists(select 1 from promotion_tasks where tournament_id=t.id and kind='announcement') then
    insert into promotion_tasks(tournament_id,kind,draft) values(t.id,'announcement','SummitWar edition #'||t.edition||': '||(select string_agg(snapshot->>'name',', ' order by priority) from entries where tournament_id=t.id and status='confirmed')||'. Watch the demos and choose the app you would actually use. Battle: /tournaments/'||t.id);
    insert into promotion_tasks(tournament_id,entry_id,kind,draft) select t.id,id,'battle_card','Download your battle card from your match page.' from entries where tournament_id=t.id;
   end if;
   t.status='locked';
  end if;
  if t.status='locked' and now()>=t.starts_at then update tournaments set status='voting' where id=t.id; t.status='voting'; end if;
  if t.status='voting' then
   for roundno in 1..3 loop
    for m in select * from matches where tournament_id=t.id and round=roundno and ends_at<=now() and winner_id is null order by position for update loop
     select count(*) into a from votes where match_id=m.id and entry_id=m.entry_a and valid;
     select count(*) into b from votes where match_id=m.id and entry_id=m.entry_b and valid;
     if a=b then select id into win from entries where id in(m.entry_a,m.entry_b) order by priority limit 1; else win=case when a>b then m.entry_a else m.entry_b end; end if;
     update matches set winner_id=win,score_a=a,score_b=b where id=m.id;
    end loop;
    if (select count(*) from matches where tournament_id=t.id and round=roundno and winner_id is not null) = (case roundno when 1 then 4 when 2 then 2 else 1 end) then
     select array_agg(winner_id order by position) into winners from matches where tournament_id=t.id and round=roundno;
     if roundno<3 then
      offsethours=case when t.daily_cycle then roundno*4 else case roundno when 1 then 24 else 40 end end; durationhours=case when t.daily_cycle then 4 else case roundno when 1 then 16 else 8 end end;
      for i in 1..(array_length(winners,1)/2) loop insert into matches(tournament_id,round,position,entry_a,entry_b,starts_at,ends_at) values(t.id,roundno+1,i,winners[i*2-1],winners[i*2],t.starts_at+make_interval(hours=>offsethours),t.starts_at+make_interval(hours=>offsethours+durationhours)) on conflict do nothing; end loop;
     else
      insert into champions(tournament_id,entry_id,spotlight_starts,spotlight_ends) values(t.id,winners[1],t.starts_at+make_interval(hours=>case when t.daily_cycle then 12 else 48 end),t.starts_at+make_interval(hours=>case when t.daily_cycle then 24 else 168 end)) on conflict do nothing;
      update tournaments set status='spotlight' where id=t.id;
      if not exists(select 1 from promotion_tasks where tournament_id=t.id and kind='champion_post') then
       insert into promotion_tasks(tournament_id,entry_id,kind,draft) values(t.id,winners[1],'champion_post',(select snapshot->>'name' from entries where id=winners[1])||' is the community-choice champion of SummitWar edition #'||t.edition||'. Discover what they built: /champions/'||t.id),(t.id,winners[1],'pin_post',case when t.daily_cycle then 'Pin the dedicated X post during the 12-hour winner spotlight.' else 'Pin the dedicated X post for five days.' end),(t.id,winners[1],'founder_interview','What did you build? Who does it help? Why did you build it?');
      end if;
     end if;
    end if;
   end loop;
  end if;
  if now()>=t.starts_at+make_interval(hours=>case when t.daily_cycle then 24 else 168 end) and exists(select 1 from champions where tournament_id=t.id) then update tournaments set status='completed' where id=t.id; end if;
 end loop;
end $$;


create or replace function public.tick() returns void language plpgsql set search_path=public as $$
declare t tournaments; next_start timestamptz; number integer; next_id uuid;
begin
 -- Serialize the daily planner; retries and concurrent cron calls cannot create duplicate editions.
 perform pg_advisory_xact_lock(hashtext('summitwar_daily_planner'));
 for t in select * from tournaments where status='registration' and registration_ends<=now() and exists(select 1 from entries where tournament_id=tournaments.id and status='confirmed' and review_status<>'approved') for update loop
  update tournaments set starts_at=next_daily_start(starts_at),registration_ends=next_daily_start(starts_at)-interval '1 hour' where id=t.id;
  insert into notifications(user_id,message) select user_id,'Voting moved to the next daily start because eight approved founders are required.' from entries where tournament_id=t.id;
 end loop;
 perform tick_before_submission();
 -- Open tomorrow's registration as soon as today's bracket locks. Never fabricate entrants or missed results.
 select * into t from tournaments where daily_cycle and status in ('locked','voting','spotlight','completed') and not archived order by starts_at desc limit 1;
 if t.id is not null and not exists(select 1 from tournaments where previous_tournament_id=t.id) and not exists(select 1 from tournaments where status='registration' and id<>t.id) then
  next_start=next_daily_start(t.starts_at);
  update edition_counter set last_edition=greatest(last_edition,(select coalesce(max(edition),0) from tournaments))+1 where id=true returning last_edition into number;
  insert into tournaments(edition,theme,status,fee_amount_cents,registration_ends,starts_at,daily_cycle,previous_tournament_id) values(number,t.theme,'registration',500,next_start-interval '1 hour',next_start,true,t.id) returning id into next_id;
  insert into audit_logs(action,target,detail) values('schedule_daily_edition',next_id,jsonb_build_object('previous',t.id,'starts_at',next_start));
 end if;
end $$;
revoke execute on function public.next_daily_start(timestamptz),public.tick(),public.tick_before_submission(),public.admin_command_before_submission(uuid,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.next_daily_start(timestamptz),public.tick(),public.tick_before_submission(),public.admin_command_before_submission(uuid,text,uuid,jsonb) to service_role;

-- END 20261011190335_daily_tournaments.sql

-- BEGIN 20261011195958_community_features.sql
-- In-app community features. No email delivery or email jobs.
create table public.product_follows(user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table public.saved_products(user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table public.feedback_replies(id uuid primary key default gen_random_uuid(),feedback_id uuid not null references feedback(id) on delete cascade,user_id uuid not null references auth.users(id),body text not null check(length(body) between 3 and 1500),created_at timestamptz not null default now());
create index replies_thread on feedback_replies(feedback_id,created_at);
alter table notifications add column event_key text;
alter table notifications add column href text;
alter table notifications add column read_at timestamptz;
create unique index notification_event_once on notifications(user_id,event_key) where event_key is not null;
create index notifications_inbox on notifications(user_id,created_at desc);
create table public.vote_risk_events(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id),match_id uuid not null references matches(id),network_hash text not null check(length(network_hash)=64),created_at timestamptz not null default now());
create index vote_risk_network on vote_risk_events(network_hash,match_id,created_at);
create table public.screenshot_jobs(product_id uuid primary key references products(id) on delete cascade,status text not null default 'queued' check(status in ('queued','processing','done','failed')),attempts integer not null default 0,updated_at timestamptz not null default now(),error text);
alter table products add column preview_captured_at timestamptz;
do $$declare name text;begin foreach name in array array['product_follows','saved_products','feedback_replies','vote_risk_events','screenshot_jobs'] loop execute format('alter table public.%I enable row level security',name);execute format('revoke all on public.%I from public,anon,authenticated',name);execute format('grant all on public.%I to service_role',name);end loop;end $$;
grant usage,select on sequence vote_risk_events_id_seq to service_role;
create function public.community_command(p_actor uuid,p_action text,p_product uuid default null,p_target uuid default null,p_body text default null,p_enabled boolean default true) returns void language plpgsql set search_path=public as $$
begin
 if not exists(select 1 from auth.users where id=p_actor and (email_confirmed_at is not null or raw_app_meta_data->>'provider'='github')) then raise exception 'Verified sign-in required';end if;
 perform pg_advisory_xact_lock(hashtext(p_actor::text));
 if p_action in ('follow','save') then
  if not exists(select 1 from products where id=p_product and published) then raise exception 'Published product required';end if;
  if p_enabled and ((select count(*) from product_follows where user_id=p_actor)+(select count(*) from saved_products where user_id=p_actor))>=500 then raise exception 'Your collection is full';end if;
  if p_action='follow' then if p_enabled then insert into product_follows(user_id,product_id) values(p_actor,p_product) on conflict do nothing;else delete from product_follows where user_id=p_actor and product_id=p_product;end if;
  else if p_enabled then insert into saved_products(user_id,product_id) values(p_actor,p_product) on conflict do nothing;else delete from saved_products where user_id=p_actor and product_id=p_product;end if;end if;
 elsif p_action='reply' then
  if not exists(select 1 from feedback f join products p on p.id=f.product_id where f.id=p_target and not f.hidden and p.published and p.owner_id=p_actor) then raise exception 'Only the founder can reply to this feedback';end if;
  if (select count(*) from feedback_replies where user_id=p_actor and created_at>now()-interval '1 minute')>=3 then raise exception 'Please wait before replying again';end if;
  insert into feedback_replies(feedback_id,user_id,body) values(p_target,p_actor,trim(p_body));
  insert into notifications(user_id,message,href) select f.user_id,'The founder replied to your feedback on '||p.name,'/products/'||p.slug from feedback f join products p on p.id=f.product_id where f.id=p_target and f.user_id<>p_actor;
 elsif p_action='read' then update notifications set read_at=now() where user_id=p_actor and (p_target is null or id=p_target) and read_at is null;
 else raise exception 'Unknown community action';end if;
end $$;
create function public.send_follow_reminders() returns void language plpgsql set search_path=public as $$
begin
 insert into notifications(user_id,message,event_key,href)
 select f.user_id,p.name||case when now()<m.ends_at-interval '30 minutes' then ' is competing. Round '||m.round||' is open.' else ' has 30 minutes left in this round. Make your final choice.' end,
 m.id::text||case when now()<m.ends_at-interval '30 minutes' then ':open' else ':closing' end,'/matches/'||m.id
 from product_follows f join products p on p.id=f.product_id join entries e on e.product_id=p.id join matches m on e.id in(m.entry_a,m.entry_b) join tournaments t on t.id=m.tournament_id
 where t.status='voting' and m.starts_at<=now() and m.ends_at>now() and m.winner_id is null
 and not exists(select 1 from entries own where own.user_id=f.user_id and own.id in(m.entry_a,m.entry_b))
 and not exists(select 1 from votes where user_id=f.user_id and match_id=m.id)
 on conflict(user_id,event_key) where event_key is not null do nothing;
end $$;
create function public.cast_protected_vote(p_actor uuid,p_match uuid,p_entry uuid,p_network text) returns void language plpgsql set search_path=public as $$
begin
 if p_network is null or p_network !~ '^[0-9a-f]{64}$' then raise exception 'Invalid vote context';end if;
 perform pg_advisory_xact_lock(hashtext(p_network||p_match::text));
 perform cast_vote(p_actor,p_match,p_entry);
 insert into vote_risk_events(user_id,match_id,network_hash) values(p_actor,p_match,p_network);
 if (select count(distinct user_id) from vote_risk_events where network_hash=p_network and match_id=p_match and created_at>now()-interval '10 minutes')>=4 then
  update votes set suspicious=true where match_id=p_match and user_id in(select user_id from vote_risk_events where network_hash=p_network and match_id=p_match and created_at>now()-interval '10 minutes');
 end if;
 delete from vote_risk_events where created_at<now()-interval '7 days';
end $$;
create function public.live_revision(p_tournament uuid) returns text language sql stable set search_path=public as $$
 select md5(coalesce((select status from tournaments where id=p_tournament),'')||coalesce((select string_agg(id::text||coalesce(winner_id::text,''),',' order by id) from matches where tournament_id=p_tournament),'')||coalesce((select count(*)::text||count(*) filter(where valid)::text from votes v join matches m on m.id=v.match_id where m.tournament_id=p_tournament),'')||coalesce((select string_agg(e.id::text||e.status||e.review_status||coalesce(p.screenshot_url,''),',' order by e.id) from entries e join products p on p.id=e.product_id where e.tournament_id=p_tournament),''));
$$;
create function public.queue_screenshot() returns trigger language plpgsql set search_path=public as $$begin insert into screenshot_jobs(product_id) values(new.id) on conflict do nothing;return new;end $$;
create trigger queue_product_preview after insert on products for each row execute function queue_screenshot();
insert into screenshot_jobs(product_id) select id from products where screenshot_url is null on conflict do nothing;
create function public.claim_screenshot() returns jsonb language plpgsql set search_path=public as $$
declare job screenshot_jobs;begin
 select * into job from screenshot_jobs where (status='queued' or status='processing' and updated_at<now()-interval '3 minutes') and attempts<3 order by updated_at for update skip locked limit 1;
 if job.product_id is null then return null;end if;
 update screenshot_jobs set status='processing',attempts=attempts+1,updated_at=now() where product_id=job.product_id;
 return (select jsonb_build_object('id',id,'url',url) from products where id=job.product_id);
end $$;
alter function public.tick() rename to tick_before_community;
create function public.tick() returns void language plpgsql set search_path=public as $$begin perform tick_before_community();perform send_follow_reminders();end $$;
revoke execute on function public.community_command(uuid,text,uuid,uuid,text,boolean),public.send_follow_reminders(),public.cast_protected_vote(uuid,uuid,uuid,text),public.live_revision(uuid),public.queue_screenshot(),public.claim_screenshot(),public.tick(),public.tick_before_community() from public,anon,authenticated;
grant execute on function public.community_command(uuid,text,uuid,uuid,text,boolean),public.send_follow_reminders(),public.cast_protected_vote(uuid,uuid,uuid,text),public.live_revision(uuid),public.queue_screenshot(),public.claim_screenshot(),public.tick(),public.tick_before_community() to service_role;

-- END 20261011195958_community_features.sql

-- BEGIN 20261012191709_extended_tournament_schedule.sql
-- New/unlocked editions use 24h quarterfinals, 24h semifinals, 12h final and 12h spotlight.
-- Preserve locked and already-running brackets and their published timestamps.
alter table public.tournaments add column extended_cycle boolean not null default false;
update public.tournaments set extended_cycle=true where status in ('draft','registration') and not exists(select 1 from matches where tournament_id=tournaments.id);
alter table public.tournaments alter column extended_cycle set default true;
-- Move existing advance-registration editions beyond their predecessor's spotlight.
update public.tournaments n set starts_at=p.starts_at+interval '72 hours',registration_ends=p.starts_at+interval '71 hours' from public.tournaments p where n.previous_tournament_id=p.id and p.extended_cycle and n.status='registration' and n.starts_at<p.starts_at+interval '72 hours' and not exists(select 1 from matches where tournament_id=n.id);
create or replace function public.admin_command_before_submission(p_actor uuid,p_action text,p_target uuid default null,p_data jsonb default '{}') returns jsonb language plpgsql set search_path=public as $$
declare t tournaments; e entries; n integer; rid uuid;
begin
 if not exists(select 1 from admin_roles where user_id=p_actor) then raise exception 'Admin access required'; end if;
 if p_action='create' then
  insert into tournaments(theme,registration_ends,starts_at) values(p_data->>'theme',(p_data->>'registration_ends')::timestamptz,(p_data->>'starts_at')::timestamptz) returning id into rid;
 elsif p_action='publish' then
  select * into t from tournaments where id=p_target for update;
  if t.id is null or t.status<>'draft' then raise exception 'Only drafts may be published'; end if;
  update edition_counter set last_edition=last_edition+1 where id returning last_edition into n;
  update tournaments set edition=n,fee_amount_cents=case when n=1 then 0 else 500 end,status='registration' where id=p_target;
 elsif p_action in ('approve','reject','waitlist','remove') then
  select tournament_id into rid from entries where id=p_target;
  select * into t from tournaments where id=rid for update;
  select * into e from entries where id=p_target for update;
  if t.status<>'registration' or now()>=t.registration_ends then raise exception 'Registration is closed'; end if;
  if e.id is null then raise exception 'Entry not found'; end if;
  if p_action='approve' then
   if e.status not in ('pending','waitlisted','approved') then raise exception 'Entry cannot be approved'; end if;
   update reservations set released=true where entry_id=e.id and expires_at<=now();
   if e.status='approved' and exists(select 1 from reservations where entry_id=e.id and not released and expires_at>now()) then return jsonb_build_object('id',e.id); end if;
   if (seat_availability(t.id)->>'available')::int<1 then update entries set status='waitlisted' where id=e.id;
   elsif t.fee_amount_cents=0 then update entries set status='confirmed' where id=e.id; update products set published=true where id=e.product_id;
   else
    if t.registration_ends<now()+interval '31 minutes' then raise exception 'At least 31 minutes needed for payment'; end if;
    update entries set status='approved' where id=e.id;
    insert into reservations(entry_id,tournament_id,expires_at) values(e.id,t.id,least(now()+interval '60 minutes',t.registration_ends));
   end if;
  else
   if e.status='confirmed' and p_action<>'remove' then raise exception 'Use remove for an accepted entry'; end if;
   update entries set status=case p_action when 'reject' then 'rejected' when 'remove' then 'removed' else 'waitlisted' end where id=e.id;
   update reservations set released=true where entry_id=e.id;
   update payments set status='refund_pending' where entry_id=e.id and status='paid';
  end if;
 elsif p_action='cancel' then
  select * into t from tournaments where id=p_target for update;
  if t.status not in ('registration','locked') or now()>=t.starts_at then raise exception 'Only cancel before participation'; end if;
  update tournaments set status='cancelled' where id=t.id;
  update reservations set released=true where tournament_id=t.id;
  update payments set status='refund_pending' where status='paid' and entry_id in(select id from entries where tournament_id=t.id);
  insert into notifications(user_id,message) select user_id,'Edition cancelled. Paid entries will be refunded.' from entries where tournament_id=t.id;
 elsif p_action='reschedule' then
  select * into t from tournaments where id=p_target for update;
  if t.status not in ('registration','cancelled') then raise exception 'Cannot reschedule locked bracket'; end if;
  if t.status='cancelled' and exists(select 1 from payments where entry_id in(select id from entries where tournament_id=t.id) and status in ('paid','refund_pending')) then raise exception 'Finish refunds before rescheduling'; end if;
  if t.status='cancelled' then update entries set status='pending' where tournament_id=t.id; end if;
  update tournaments set status='registration',registration_ends=(p_data->>'registration_ends')::timestamptz,starts_at=(p_data->>'starts_at')::timestamptz where id=t.id;
  update matches set starts_at=(p_data->>'starts_at')::timestamptz+make_interval(hours=>case when t.extended_cycle then case round when 1 then 0 when 2 then 24 else 48 end when t.daily_cycle then (round-1)*4 else case round when 1 then 0 when 2 then 24 else 40 end end),ends_at=(p_data->>'starts_at')::timestamptz+make_interval(hours=>case when t.extended_cycle then case round when 1 then 24 when 2 then 48 else 60 end when t.daily_cycle then round*4 else case round when 1 then 24 when 2 then 40 else 48 end end) where tournament_id=t.id;
  insert into notifications(user_id,message) select user_id,'Your edition was rescheduled. Check the updated schedule.' from entries where tournament_id=t.id;
 elsif p_action='invalidate' then
  if length(coalesce(p_data->>'reason',''))<3 then raise exception 'Reason required'; end if;
  select tournament_id into rid from matches where id=(select match_id from votes where id=p_target);
  perform 1 from tournaments where id=rid for update;
  if not exists(select 1 from matches m join votes v on v.match_id=m.id where v.id=p_target and m.winner_id is null and now()<m.ends_at) then raise exception 'Results already frozen'; end if;
  update votes set valid=false,invalidation_reason=p_data->>'reason' where id=p_target;
 elsif p_action='fulfill' then update promotion_tasks set status='completed',completed_at=now(),draft=coalesce(p_data->>'draft',draft) where id=p_target;
 elsif p_action='interview' then update champions set interview=p_data where tournament_id=p_target;
 elsif p_action='moderate' then update feedback set hidden=true where id=p_target; update reports set status='resolved' where feedback_id=p_target;
 elsif p_action='archive' then update tournaments set archived=true where id=p_target and status in ('completed','cancelled');
 else raise exception 'Unknown admin action'; end if;
 insert into audit_logs(actor,action,target,detail) values(p_actor,p_action,coalesce(p_target,rid),p_data);
 return jsonb_build_object('id',coalesce(rid,p_target));
end $$;

create or replace function public.tick_before_submission() returns void language plpgsql set search_path=public as $$
declare t tournaments; m matches; ids uuid[]; winners uuid[]; a integer; b integer; win uuid; roundno integer; offsethours integer; durationhours integer; i integer;
begin
 for t in select * from tournaments where status in ('registration','locked','voting','spotlight') order by edition for update skip locked loop
  update reservations set released=true where tournament_id=t.id and expires_at<=now();
  if t.status='registration' and now()>=t.registration_ends then
   if (select count(*) from entries where tournament_id=t.id and status='confirmed')<>8 then
    update tournaments set starts_at=public.next_daily_start(starts_at),registration_ends=public.next_daily_start(starts_at)-interval '1 hour' where id=t.id;
    insert into notifications(user_id,message) select user_id,'Voting was rescheduled because eight confirmed entrants are required.' from entries where tournament_id=t.id;
    continue;
   end if;
   if not exists(select 1 from matches where tournament_id=t.id) then
    select array_agg(id) into ids from (select id from entries where tournament_id=t.id and status='confirmed' order by random()) x;
    for i in 1..8 loop update entries set priority=i,snapshot=(select to_jsonb(p) from products p where p.id=entries.product_id) where id=ids[i]; end loop;
    for i in 1..4 loop insert into matches(tournament_id,round,position,entry_a,entry_b,starts_at,ends_at) values(t.id,1,i,ids[i*2-1],ids[i*2],t.starts_at,t.starts_at+make_interval(hours=>case when t.extended_cycle then 24 when t.daily_cycle then 4 else 24 end)); end loop;
   end if;
   update tournaments set status='locked' where id=t.id;
   if not exists(select 1 from promotion_tasks where tournament_id=t.id and kind='announcement') then
    insert into promotion_tasks(tournament_id,kind,draft) values(t.id,'announcement','SummitWar edition #'||t.edition||': '||(select string_agg(snapshot->>'name',', ' order by priority) from entries where tournament_id=t.id and status='confirmed')||'. Watch the demos and choose the app you would actually use. Battle: /tournaments/'||t.id);
    insert into promotion_tasks(tournament_id,entry_id,kind,draft) select t.id,id,'battle_card','Download your battle card from your match page.' from entries where tournament_id=t.id;
   end if;
   t.status='locked';
  end if;
  if t.status='locked' and now()>=t.starts_at then update tournaments set status='voting' where id=t.id; t.status='voting'; end if;
  if t.status='voting' then
   for roundno in 1..3 loop
    for m in select * from matches where tournament_id=t.id and round=roundno and ends_at<=now() and winner_id is null order by position for update loop
     select count(*) into a from votes where match_id=m.id and entry_id=m.entry_a and valid;
     select count(*) into b from votes where match_id=m.id and entry_id=m.entry_b and valid;
     if a=b then select id into win from entries where id in(m.entry_a,m.entry_b) order by priority limit 1; else win=case when a>b then m.entry_a else m.entry_b end; end if;
     update matches set winner_id=win,score_a=a,score_b=b where id=m.id;
    end loop;
    if (select count(*) from matches where tournament_id=t.id and round=roundno and winner_id is not null) = (case roundno when 1 then 4 when 2 then 2 else 1 end) then
     select array_agg(winner_id order by position) into winners from matches where tournament_id=t.id and round=roundno;
     if roundno<3 then
      offsethours=case when t.extended_cycle then roundno*24 when t.daily_cycle then roundno*4 else case roundno when 1 then 24 else 40 end end; durationhours=case when t.extended_cycle then case roundno when 1 then 24 else 12 end when t.daily_cycle then 4 else case roundno when 1 then 16 else 8 end end;
      for i in 1..(array_length(winners,1)/2) loop insert into matches(tournament_id,round,position,entry_a,entry_b,starts_at,ends_at) values(t.id,roundno+1,i,winners[i*2-1],winners[i*2],t.starts_at+make_interval(hours=>offsethours),t.starts_at+make_interval(hours=>offsethours+durationhours)) on conflict do nothing; end loop;
     else
      insert into champions(tournament_id,entry_id,spotlight_starts,spotlight_ends) values(t.id,winners[1],t.starts_at+make_interval(hours=>case when t.extended_cycle then 60 when t.daily_cycle then 12 else 48 end),t.starts_at+make_interval(hours=>case when t.extended_cycle then 72 when t.daily_cycle then 24 else 168 end)) on conflict do nothing;
      update tournaments set status='spotlight' where id=t.id;
      if not exists(select 1 from promotion_tasks where tournament_id=t.id and kind='champion_post') then
       insert into promotion_tasks(tournament_id,entry_id,kind,draft) values(t.id,winners[1],'champion_post',(select snapshot->>'name' from entries where id=winners[1])||' is the community-choice champion of SummitWar edition #'||t.edition||'. Discover what they built: /champions/'||t.id),(t.id,winners[1],'pin_post',case when t.daily_cycle then 'Pin the dedicated X post during the 12-hour winner spotlight.' else 'Pin the dedicated X post for five days.' end),(t.id,winners[1],'founder_interview','What did you build? Who does it help? Why did you build it?');
      end if;
     end if;
    end if;
   end loop;
  end if;
  if now()>=t.starts_at+make_interval(hours=>case when t.extended_cycle then 72 when t.daily_cycle then 24 else 168 end) and exists(select 1 from champions where tournament_id=t.id) then update tournaments set status='completed' where id=t.id; end if;
 end loop;
end $$;


create or replace function public.tick_before_community() returns void language plpgsql set search_path=public as $$
declare t tournaments; next_start timestamptz; number integer; next_id uuid;
begin
 -- Serialize the daily planner; retries and concurrent cron calls cannot create duplicate editions.
 perform pg_advisory_xact_lock(hashtext('summitwar_daily_planner'));
 for t in select * from tournaments where status='registration' and registration_ends<=now() and exists(select 1 from entries where tournament_id=tournaments.id and status='confirmed' and review_status<>'approved') for update loop
  update tournaments set starts_at=next_daily_start(starts_at),registration_ends=next_daily_start(starts_at)-interval '1 hour' where id=t.id;
  insert into notifications(user_id,message) select user_id,'Voting moved to the next daily start because eight approved founders are required.' from entries where tournament_id=t.id;
 end loop;
 perform tick_before_submission();
 -- Open tomorrow's registration as soon as today's bracket locks. Never fabricate entrants or missed results.
 select * into t from tournaments where daily_cycle and status in ('locked','voting','spotlight','completed') and not archived order by starts_at desc limit 1;
 if t.id is not null and not exists(select 1 from tournaments where previous_tournament_id=t.id) and not exists(select 1 from tournaments where status='registration' and id<>t.id) then
  next_start=next_daily_start(t.starts_at);if t.extended_cycle then next_start=greatest(next_start,t.starts_at+interval '72 hours');end if;
  update edition_counter set last_edition=greatest(last_edition,(select coalesce(max(edition),0) from tournaments))+1 where id=true returning last_edition into number;
  insert into tournaments(edition,theme,status,fee_amount_cents,registration_ends,starts_at,daily_cycle,previous_tournament_id) values(number,t.theme,'registration',500,next_start-interval '1 hour',next_start,true,t.id) returning id into next_id;
  insert into audit_logs(action,target,detail) values('schedule_daily_edition',next_id,jsonb_build_object('previous',t.id,'starts_at',next_start));
 end if;
end $$;
revoke execute on function public.next_daily_start(timestamptz),public.tick_before_community(),public.tick_before_submission(),public.admin_command_before_submission(uuid,text,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.next_daily_start(timestamptz),public.tick_before_community(),public.tick_before_submission(),public.admin_command_before_submission(uuid,text,uuid,jsonb) to service_role;

-- END 20261012191709_extended_tournament_schedule.sql

-- BEGIN 20261015102148_guest_voting.sql
-- Guest ballots share the existing score, moderation and freeze rules; no auth user is created.
alter table public.votes alter column user_id drop not null;
alter table public.votes add column voter_hash text check(voter_hash ~ '^[0-9a-f]{64}$');
alter table public.votes add column network_hash text check(network_hash ~ '^[0-9a-f]{64}$');
alter table public.votes add column x_handle text check(x_handle ~ '^[a-z0-9_]{1,15}$');
alter table public.votes add constraint vote_identity_required check(user_id is not null or voter_hash is not null);
create unique index one_browser_vote on public.votes(match_id,voter_hash) where voter_hash is not null;
create index guest_vote_network on public.votes(network_hash,match_id,created_at) where network_hash is not null;
create table public.voting_links(
 match_id uuid not null references public.matches(id),voter_hash text not null check(voter_hash ~ '^[0-9a-f]{64}$'),
 token_hash text not null unique check(token_hash ~ '^[0-9a-f]{64}$'),actor_id uuid references auth.users(id),
 expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now(),primary key(match_id,voter_hash));
create table public.guest_vote_limits(network_hash text primary key check(network_hash ~ '^[0-9a-f]{64}$'),window_start timestamptz not null,hits integer not null);
create index voting_link_expiry on public.voting_links(expires_at);
create index guest_vote_limit_expiry on public.guest_vote_limits(window_start);
create index guest_voter_recent on public.votes(voter_hash,created_at) where voter_hash is not null;
alter table public.voting_links enable row level security;
alter table public.guest_vote_limits enable row level security;
revoke all on public.voting_links,public.guest_vote_limits from public,anon,authenticated;
grant all on public.voting_links,public.guest_vote_limits to service_role;

create function public.issue_voting_link(p_match uuid,p_voter text,p_token text,p_network text,p_actor uuid default null) returns timestamptz language plpgsql set search_path=public as $$
declare m matches; deadline timestamptz; bucket timestamptz; attempts integer;
begin
 if p_voter is null or p_voter !~ '^[0-9a-f]{64}$' or p_token is null or p_token !~ '^[0-9a-f]{64}$' or p_network is null or p_network !~ '^[0-9a-f]{64}$' then raise exception 'Invalid voting context';end if;
 select tournament_id into m.tournament_id from matches where id=p_match;
 perform 1 from tournaments where id=m.tournament_id for update;
 select * into m from matches where id=p_match for update;
 if m.id is null or clock_timestamp()<m.starts_at or clock_timestamp()>=m.ends_at or m.winner_id is not null or not exists(select 1 from tournaments where id=m.tournament_id and status='voting') then raise exception 'Match is not open';end if;
 if p_actor is not null and not exists(select 1 from auth.users where id=p_actor) then raise exception 'Invalid account';end if;
 if exists(select 1 from entries where id in(m.entry_a,m.entry_b) and user_id=p_actor) then raise exception 'Founders cannot vote in their own match';end if;
 if exists(select 1 from votes where match_id=p_match and (voter_hash=p_voter or user_id=p_actor)) then raise exception 'Your final vote is already recorded';end if;
 bucket=to_timestamp(floor(extract(epoch from clock_timestamp())/600)*600);
 insert into guest_vote_limits(network_hash,window_start,hits) values(p_network,bucket,1) on conflict(network_hash) do update set hits=case when guest_vote_limits.window_start=excluded.window_start then guest_vote_limits.hits+1 else 1 end,window_start=excluded.window_start returning hits into attempts;
 if attempts>20 then raise exception 'Too many voting link requests. Please wait ten minutes';end if;
 deadline=least(clock_timestamp()+interval '10 minutes',m.ends_at);
 insert into voting_links(match_id,voter_hash,token_hash,actor_id,expires_at) values(p_match,p_voter,p_token,p_actor,deadline)
 on conflict(match_id,voter_hash) do update set token_hash=excluded.token_hash,actor_id=excluded.actor_id,expires_at=excluded.expires_at,used_at=null,created_at=now();
 return deadline;
end $$;

create function public.cast_guest_vote(p_match uuid,p_entry uuid,p_voter text,p_token text,p_network text,p_handle text default null,p_actor uuid default null) returns void language plpgsql set search_path=public as $$
declare m matches; link voting_links;
begin
 if p_voter is null or p_voter !~ '^[0-9a-f]{64}$' or p_token is null or p_token !~ '^[0-9a-f]{64}$' or p_network is null or p_network !~ '^[0-9a-f]{64}$' then raise exception 'Invalid voting context';end if;
 if p_handle is not null and p_handle !~ '^[a-z0-9_]{1,15}$' then raise exception 'Enter a valid X handle';end if;
 select tournament_id into m.tournament_id from matches where id=p_match;
 perform 1 from tournaments where id=m.tournament_id for update;
 select * into m from matches where id=p_match for update;
 if m.id is null or clock_timestamp()<m.starts_at or clock_timestamp()>=m.ends_at or m.winner_id is not null or not exists(select 1 from tournaments where id=m.tournament_id and status='voting') then raise exception 'Match is not open';end if;
 if p_entry is null or p_entry not in(m.entry_a,m.entry_b) then raise exception 'Invalid contender';end if;
 select * into link from voting_links where match_id=p_match and voter_hash=p_voter and token_hash=p_token for update;
 if link.match_id is null or link.expires_at<=clock_timestamp() or link.used_at is not null then raise exception 'Voting link is invalid, expired or already used';end if;
 if link.actor_id is distinct from p_actor then raise exception 'Your account changed. Create a new voting link';end if;
 if exists(select 1 from entries where id in(m.entry_a,m.entry_b) and user_id=p_actor) then raise exception 'Founders cannot vote in their own match';end if;
 if exists(select 1 from votes where match_id=p_match and (voter_hash=p_voter or user_id=p_actor)) then raise exception 'Your final vote is already recorded';end if;
 if (select count(*) from votes where voter_hash=p_voter and created_at>now()-interval '1 minute')>=6 then raise exception 'Please wait before voting again';end if;
 insert into votes(match_id,entry_id,user_id,voter_hash,network_hash,x_handle) values(p_match,p_entry,p_actor,p_voter,p_network,p_handle);
 update voting_links set used_at=clock_timestamp() where match_id=p_match and voter_hash=p_voter;
 if (select count(distinct voter_hash) from votes where match_id=p_match and network_hash=p_network and created_at>now()-interval '10 minutes')>=4 then
  update votes set suspicious=true where match_id=p_match and network_hash=p_network and created_at>now()-interval '10 minutes';
 end if;
end $$;
revoke execute on function public.issue_voting_link(uuid,text,text,text,uuid),public.cast_guest_vote(uuid,uuid,text,text,text,text,uuid) from public,anon,authenticated;
grant execute on function public.issue_voting_link(uuid,text,text,text,uuid),public.cast_guest_vote(uuid,uuid,text,text,text,text,uuid) to service_role;
-- Used vote records remain; obsolete token hashes and network counters can be discarded.
alter function public.tick() rename to tick_before_guest_voting;
create function public.tick() returns void language plpgsql set search_path=public as $$begin
 perform tick_before_guest_voting();
 delete from voting_links where expires_at<now()-interval '1 day';
 delete from guest_vote_limits where window_start<now()-interval '1 day';
 update votes set network_hash=null where network_hash is not null and created_at<now()-interval '7 days';
end $$;
revoke execute on function public.tick(),public.tick_before_guest_voting() from public,anon,authenticated;
grant execute on function public.tick(),public.tick_before_guest_voting() to service_role;

-- END 20261015102148_guest_voting.sql

-- BEGIN 20261017101030_paid_promotions.sql
create function public.promotion_ends(p_tournament uuid) returns timestamptz language sql stable set search_path=public as $$
 select coalesce((select spotlight_ends from champions where tournament_id=t.id),t.starts_at+make_interval(hours=>case when t.extended_cycle then 72 when t.daily_cycle then 24 else 168 end)) from tournaments t where id=p_tournament;
$$;
create function public.promotion_price(p_slot integer) returns integer language sql immutable set search_path=public as $$select case when p_slot in(1,4) then 10000 when p_slot in(2,5) then 70000 when p_slot in(3,6) then 5000 else null end$$;
create table public.promotion_orders(id uuid primary key,user_id uuid not null references auth.users(id),tournament_id uuid not null references tournaments(id),slots integer[] not null,amount integer not null check(amount>0),name text not null,url text not null,tagline text not null,logo_url text,status text not null default 'pending' check(status in('pending','paid','expired','removed')),reserved_until timestamptz not null,checkout_id text unique,checkout_url text,created_at timestamptz not null default now());
create table public.promotion_slots(tournament_id uuid not null references tournaments(id),position integer not null check(position between 1 and 6),order_id uuid references promotion_orders(id),primary key(tournament_id,position));
create table public.promotion_payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references promotion_orders(id),checkout_id text not null,intent_id text not null unique,amount integer not null,currency text not null check(currency='usd'),status text not null check(status in('paid','refund_pending','refunded','disputed')),refund_id text,refund_attempts integer not null default 0,last_refund_error text,created_at timestamptz not null default now());
create table public.promotion_payment_signals(intent_id text primary key,order_id uuid not null references promotion_orders(id),status text not null check(status in('refunded','disputed')));
create index promotion_owner on promotion_orders(user_id,created_at);
create index promotion_refunds on promotion_payments(status) where status='refund_pending';
do $$declare name text;begin foreach name in array array['promotion_orders','promotion_slots','promotion_payments','promotion_payment_signals'] loop execute format('alter table public.%I enable row level security',name);execute format('revoke all on public.%I from public,anon,authenticated',name);execute format('grant all on public.%I to service_role',name);end loop;end$$;

create function public.promotion_inventory(p_tournament uuid) returns jsonb language sql stable set search_path=public as $$
 select coalesce(jsonb_agg(jsonb_build_object('position',position,'price',promotion_price(position),'state',case when not live then 'closed' when occupied and status='paid' then 'paid' when occupied then 'reserved' else 'available' end,'name',case when occupied and status='paid' and live then name end,'url',case when occupied and status='paid' and live then url end,'tagline',case when occupied and status='paid' and live then tagline end,'logo_url',case when occupied and status='paid' and live then logo_url end) order by position),'[]'::jsonb) from (
 select g.position,o.status,o.name,o.url,o.tagline,o.logo_url,(t.edition is not null and t.status in('registration','locked','voting','spotlight') and promotion_ends(t.id)>now()) live,
 (o.status='pending' and o.reserved_until>now() or o.status='paid' and exists(select 1 from promotion_payments p where p.order_id=o.id and p.status='paid')) occupied
 from tournaments t cross join generate_series(1,6) g(position) left join promotion_slots s on s.tournament_id=t.id and s.position=g.position left join promotion_orders o on o.id=s.order_id where t.id=p_tournament) x;
$$;

create function public.reserve_promotion(p_actor uuid,p_tournament uuid,p_slots integer[],p_request uuid,p_product jsonb) returns uuid language plpgsql set search_path=public as $$
declare t tournaments; chosen integer[]; total integer; deadline timestamptz; existing promotion_orders;begin
 if not exists(select 1 from auth.users where id=p_actor and (email_confirmed_at is not null or raw_app_meta_data->>'provider'='github' or raw_app_meta_data->'providers' ? 'github')) then raise exception 'Sign in before booking promotion';end if;
 select * into t from tournaments where id=p_tournament for update;
 deadline=promotion_ends(t.id);
 if t.id is null or t.edition is null or t.status not in('registration','locked','voting','spotlight') or deadline<clock_timestamp()+interval '31 minutes' then raise exception 'Promotion booking is closed for this edition';end if;
 select array_agg(distinct slot order by slot),sum(promotion_price(slot)) into chosen,total from unnest(p_slots) slot;
 if chosen is null or array_length(chosen,1)>6 or exists(select 1 from unnest(chosen) slot where slot not between 1 and 6) or array_position(p_slots,null) is not null or array_length(chosen,1)<>array_length(p_slots,1) then raise exception 'Choose one or more distinct promotion cards';end if;
 select * into existing from promotion_orders where id=p_request;
 if existing.id is not null then if existing.user_id<>p_actor or existing.tournament_id<>t.id or existing.slots<>chosen then raise exception 'Booking request mismatch';end if;return existing.id;end if;
 if length(trim(coalesce(p_product->>'name','')))<2 or length(p_product->>'name')>80 or length(coalesce(p_product->>'tagline',''))>180 or coalesce(p_product->>'url','') !~ '^https?://' then raise exception 'Invalid promotion details';end if;
 if (select count(*) from promotion_orders where user_id=p_actor and created_at>now()-interval '1 minute')>=3 then raise exception 'Please wait before making another booking';end if;
 insert into promotion_slots(tournament_id,position) select t.id,generate_series(1,6) on conflict do nothing;
 if exists(select 1 from promotion_slots s join promotion_orders o on o.id=s.order_id where s.tournament_id=t.id and s.position=any(chosen) and (o.status='pending' and o.reserved_until>clock_timestamp() or o.status='paid' and exists(select 1 from promotion_payments pay where pay.order_id=o.id and pay.status='paid'))) then raise exception 'One of these promotion cards is already taken';end if;
 insert into promotion_orders(id,user_id,tournament_id,slots,amount,name,url,tagline,logo_url,reserved_until) values(p_request,p_actor,t.id,chosen,total,trim(p_product->>'name'),p_product->>'url',coalesce(p_product->>'tagline',''),p_product->>'logo_url',least(clock_timestamp()+interval '60 minutes',deadline));
 update promotion_slots set order_id=p_request where tournament_id=t.id and position=any(chosen);
 return p_request;
end $$;

create function public.fulfill_promotion(p_event text,p_type text,p_order uuid,p_checkout text,p_intent text,p_amount integer,p_currency text) returns text language plpgsql set search_path=public as $$
declare o promotion_orders; t tournaments; decision text;begin
 select tournament_id into o.tournament_id from promotion_orders where id=p_order;select * into t from tournaments where id=o.tournament_id for update;select * into o from promotion_orders where id=p_order for update;
 if o.id is null or p_amount<>o.amount or p_currency<>'usd' then raise exception 'Promotion amount or currency mismatch';end if;
 if exists(select 1 from webhook_events where id=p_event) then return 'duplicate';end if;
 if exists(select 1 from promotion_payments where intent_id=p_intent) then insert into webhook_events(id,type) values(p_event,p_type);return 'duplicate';end if;
 decision='refund_pending';
 if o.status in('pending','expired') and t.status in('registration','locked','voting','spotlight') and clock_timestamp()<promotion_ends(t.id) and (o.checkout_id is null or o.checkout_id=p_checkout) and not exists(select 1 from promotion_payments where order_id=o.id and status='paid') and (select count(*) from promotion_slots where tournament_id=t.id and position=any(o.slots) and order_id=o.id)=array_length(o.slots,1) then decision='paid';end if;
 select coalesce((select status from promotion_payment_signals where intent_id=p_intent),decision) into decision;
 insert into promotion_payments(order_id,checkout_id,intent_id,amount,currency,status) values(o.id,p_checkout,p_intent,p_amount,p_currency,decision);
 if decision='paid' then update promotion_orders set status='paid' where id=o.id;elsif o.status in('pending','expired') then update promotion_orders set status='expired' where id=o.id;end if;
 insert into webhook_events(id,type) values(p_event,p_type);return decision;
end$$;
create function public.promotion_signal(p_event text,p_type text,p_order uuid,p_intent text,p_status text) returns void language plpgsql set search_path=public as $$begin
 if p_status not in('refunded','disputed') then raise exception 'Invalid payment status';end if;
 perform 1 from tournaments where id=(select tournament_id from promotion_orders where id=p_order) for update;
 if exists(select 1 from webhook_events where id=p_event) then return;end if;
 insert into promotion_payment_signals(intent_id,order_id,status) values(p_intent,p_order,p_status) on conflict(intent_id) do update set status=case when promotion_payment_signals.status='refunded' then 'refunded' else excluded.status end;
 update promotion_payments set status=case when status='refunded' then 'refunded' else p_status end where intent_id=p_intent and order_id=p_order;
 insert into webhook_events(id,type) values(p_event,p_type);
end$$;
create function public.remove_promotion(p_actor uuid,p_order uuid,p_reason text) returns void language plpgsql set search_path=public as $$begin
 if not exists(select 1 from admin_roles where user_id=p_actor) or length(trim(coalesce(p_reason,'')))<3 then raise exception 'Admin access and a removal reason are required';end if;
 perform 1 from tournaments where id=(select tournament_id from promotion_orders where id=p_order) for update;
 update promotion_orders set status='removed' where id=p_order;
 update promotion_payments set status='refund_pending' where order_id=p_order and status='paid';
 insert into audit_logs(actor,action,target,detail) values(p_actor,'remove_promotion',p_order,jsonb_build_object('reason',p_reason));
end$$;
alter function public.tick() rename to tick_before_promotions;
create function public.tick() returns void language plpgsql set search_path=public as $$begin
 perform tick_before_promotions();
 update promotion_orders set status='expired' where status='pending' and reserved_until<=now();
 update promotion_payments set status='refund_pending' where status='paid' and order_id in(select o.id from promotion_orders o join tournaments t on t.id=o.tournament_id where t.status='cancelled');
 update promotion_orders set status='expired' where status='paid' and promotion_ends(tournament_id)<=now();
end$$;
alter function public.live_revision(uuid) rename to live_revision_before_promotions;
create function public.live_revision(p_tournament uuid) returns text language sql stable set search_path=public as $$
 select md5(live_revision_before_promotions(p_tournament)||coalesce((select string_agg(id::text||status,',' order by id) from promotion_orders where tournament_id=p_tournament),'')||coalesce((select string_agg(p.id::text||p.status,',' order by p.id) from promotion_payments p join promotion_orders o on o.id=p.order_id where o.tournament_id=p_tournament),''));
$$;
revoke execute on function public.live_revision(uuid),public.live_revision_before_promotions(uuid) from public,anon,authenticated;
grant execute on function public.live_revision(uuid),public.live_revision_before_promotions(uuid) to service_role;
revoke execute on function public.promotion_ends(uuid),public.promotion_price(integer),public.promotion_inventory(uuid),public.reserve_promotion(uuid,uuid,integer[],uuid,jsonb),public.fulfill_promotion(text,text,uuid,text,text,integer,text),public.promotion_signal(text,text,uuid,text,text),public.remove_promotion(uuid,uuid,text),public.tick(),public.tick_before_promotions() from public,anon,authenticated;
grant execute on function public.promotion_ends(uuid),public.promotion_price(integer),public.promotion_inventory(uuid),public.reserve_promotion(uuid,uuid,integer[],uuid,jsonb),public.fulfill_promotion(text,text,uuid,text,text,integer,text),public.promotion_signal(text,text,uuid,text,text),public.remove_promotion(uuid,uuid,text),public.tick(),public.tick_before_promotions() to service_role;

